  checkRedisCache(): Promise<SubsystemCheckResult>;
  checkPaymentGateways(): Promise<SubsystemCheckResult>;
  checkSmsGateway(): Promise<SubsystemCheckResult>;
  checkDispatchEngine(): Promise<SubsystemCheckResult>;
